import pandas as pd

def clean(df):
    df = df.copy()
    # standardise island labels
    if 'island' in df.columns:
        df['island'] = df['island'].astype(str).str.strip()
        island_map = {'Torgerson': 'Torgersen', 'Bisco': 'Biscoe'}
        df['island'] = df['island'].replace(island_map)
    # standardise sex labels
    if 'sex' in df.columns:
        df['sex'] = df['sex'].astype(str).str.strip().str.lower()
    # body_mass_g is text with commas / written numbers
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = df['body_mass_g'].astype(str).str.replace(',', '', regex=False)
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    # numeric columns that may be stored as text
    for col in ['flipper_length_mm', 'bill_length_mm', 'bill_depth_mm', 'year']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    # remove exact duplicate rows and duplicate penguin_id
    df = df.drop_duplicates()
    if 'penguin_id' in df.columns:
        df = df.drop_duplicates(subset=['penguin_id'], keep='first')
    return df

def answer(df):
    dfc = clean(df)
    # total body mass per species
    totals = dfc.groupby('species', dropna=False)['body_mass_g'].sum()
    # drop groups with missing species key
    result = {}
    for sp, val in totals.items():
        if pd.isna(sp):
            continue
        # return as int grams
        result[str(sp)] = int(round(val)) if pd.notna(val) else None
    return result
